let data = $json.body ?? $json;

if (typeof data === 'string') {
  try {
    data = JSON.parse(data);
  } catch {
    data = {};
  }
}

if (!data || typeof data !== 'object' || Array.isArray(data)) {
  data = {};
}

const normalized = {
  client_name: String(data.client_name ?? '').trim(),
  brand_name: String(data.brand_name ?? '').trim(),
  product: String(data.product ?? '').trim(),
  campaign_goal: String(data.campaign_goal ?? '').trim(),
  target_audience: String(data.target_audience ?? '').trim(),
  platform: String(data.platform ?? '').trim(),
  video_duration: Number(data.video_duration ?? 30),
  tone: String(data.tone ?? 'Professional').trim(),
  brand_guidelines: String(data.brand_guidelines ?? '').trim()
};

const requiredFields = [
  'client_name',
  'brand_name',
  'product',
  'campaign_goal',
  'target_audience',
  'platform'
];

const missing_fields = requiredFields.filter(
  field => !normalized[field]
);

return {
  ...normalized,
  is_valid: missing_fields.length === 0,
  missing_fields
};

function parseContent(value) {
  if (typeof value !== "string") return value;
  const cleaned = value.trim()
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/, "");
  return JSON.parse(cleaned);
}

const content = $json.choices?.[0]?.message?.content;
if (!content) {
  throw new Error("OpenRouter returned no analysis content. Check the model response.");
}

const analysis = parseContent(
  Array.isArray(content) ? content.map(x => x.text ?? "").join("\n") : content
);

const brief = $("Normalize & Validate Brief").first().json;
const required = [
  "campaign_objective",
  "audience",
  "product_positioning",
  "creative_direction"
];
const missing = required.filter(key => !analysis?.[key]);

if (missing.length) {
  throw new Error("AI analysis missing fields: " + missing.join(", "));
}

return {
  brief,
  analysis
};

function parseContent(value) {
  if (typeof value !== "string") return value;
  const cleaned = value.trim()
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/, "");
  return JSON.parse(cleaned);
}

const response = $input.first().json;
const content = response.choices?.[0]?.message?.content;

if (!content) {
  throw new Error("No creative concepts returned by the model.");
}

const result = parseContent(
  Array.isArray(content) ? content.map(x => x.text ?? "").join("\n") : content
);

if (!Array.isArray(result.concepts) || result.concepts.length !== 3) {
  throw new Error(
    `Expected exactly 3 concepts; received ${result.concepts?.length ?? 0}.`
  );
}

const context = $("Parse Brief Analysis").first().json;

return result.concepts.map((concept, index) => ({
  json: {
    ...context,
    concept_number: index + 1,
    concept
  },
  pairedItem: { item: 0 }
}));

function parseContent(value) {
  if (typeof value !== "string") return value;
  const cleaned = value.trim()
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/, "");
  return JSON.parse(cleaned);
}

const content = $json.choices?.[0]?.message?.content;
if (!content) throw new Error("No scoring response returned by the model.");

const review = parseContent(
  Array.isArray(content) ? content.map(x => x.text ?? "").join("\n") : content
);

// Accept scores either inside { scores: {...} } or directly at the root.
const source = review.scores ?? review;
const limits = {
  campaign_relevance: { max: 25, aliases: ["campaign_relevance", "campaignRelevance", "campaign_relevance_score"] },
  audience_relevance: { max: 25, aliases: ["audience_relevance", "audienceRelevance", "audience_relevance_score"] },
  brand_alignment: { max: 20, aliases: ["brand_alignment", "brandAlignment", "brand_alignment_score"] },
  creativity: { max: 15, aliases: ["creativity", "creative_score", "creativity_score"] },
  production_feasibility: { max: 15, aliases: ["production_feasibility", "productionFeasibility", "production_feasibility_score"] }
};

function readScore(aliases, max) {
  let raw;
  for (const key of aliases) {
    if (source[key] !== undefined && source[key] !== null) {
      raw = source[key];
      break;
    }
  }
  if (raw === undefined && source.total_scores && typeof source.total_scores === "object") {
    for (const key of aliases) {
      if (source.total_scores[key] !== undefined) { raw = source.total_scores[key]; break; }
    }
  }
  if (raw && typeof raw === "object") raw = raw.score ?? raw.value ?? raw.points;
  if (typeof raw === "string") {
    const fraction = raw.match(/(-?\d+(?:\.\d+)?)\s*\/\s*(\d+(?:\.\d+)?)/);
    if (fraction) {
      const numerator = Number(fraction[1]);
      const denominator = Number(fraction[2]);
      if (denominator > 0) raw = (numerator / denominator) * max;
    } else {
      const match = raw.match(/-?\d+(?:\.\d+)?/);
      raw = match ? Number(match[0]) : NaN;
    }
  }
  let value = Number(raw);
  if (!Number.isFinite(value)) {
    throw new Error(`Model did not return a numeric score for ${aliases[0]}. Received: ${JSON.stringify(raw)}. Full response: ${JSON.stringify(review).slice(0,1200)}`);
  }
  // If the model returned a percentage on a 0-100 scale, convert it to this category's maximum.
  if (value > max && value <= 100) value = (value / 100) * max;
  if (value < 0 || value > max) {
    throw new Error(`Score for ${aliases[0]} is out of range after normalization: ${value}; expected 0-${max}.`);
  }
  return Math.round(value);
}

const scores = {};
for (const [key, config] of Object.entries(limits)) {
  scores[key] = readScore(config.aliases, config.max);
}

const conceptItem = $("Parse & Split Concepts").item.json;
const total = Object.values(scores).reduce((sum, value) => sum + value, 0);

return {
  concept_number: conceptItem.concept_number,
  concept: conceptItem.concept,
  scores,
  total_score: total,
  quality_status: total >= 80
    ? "Recommended for human review"
    : total >= 60
      ? "Needs review"
      : "Rework suggested",
  feedback: String(review.feedback ?? review.explanation ?? ""),
  improvements: Array.isArray(review.improvements) ? review.improvements : []
};

const results = $input.all().map(item=>item.json).sort((a,b)=>a.concept_number-b.concept_number);
const brief = $("Normalize & Validate Brief").first().json;
return [{json:{
  success:true,
  client:brief.client_name,
  brand:brief.brand_name,
  campaign_goal:brief.campaign_goal,
  platform:brief.platform,
  generated_at:new Date().toISOString(),
  concept_count:results.length,
  concepts:results,
  note:"AI scores are advisory. A human creative reviewer should approve concepts before production."
}}];
